INSERT INTO settings (skey, lang, value) VALUES
('meta_title', 'fr', 'Heaven of Web — Création de sites web, logos et référencement à Angers'),
('meta_description', 'fr', 'Agence web à Angers : création de sites internet, identité visuelle, référencement naturel (SEO) et contenus pour réseaux sociaux. Devis gratuit.'),
('hero_title', 'fr', 'Nous construisons votre présence en ligne, pas seulement un site web.'),
('hero_subtitle', 'fr', 'Sites internet, logos, référencement et réseaux sociaux pour les artisans et les entreprises qui veulent être trouvés, puis choisis.'),
('about_title', 'fr', 'Une équipe à taille humaine, un objectif : que votre site vous amène des clients'),
('about_text', 'fr', 'Heaven of Web conçoit des sites web professionnels, des identités visuelles et des contenus pour les réseaux sociaux, avec le référencement naturel pensé dès la première maquette.\n\nNous travaillons surtout avec des artisans et des entreprises du bâtiment, de l’énergie et des services : des métiers où un client cherche sur Google, compare deux ou trois sites, puis appelle celui qui inspire confiance. C’est ce site-là que nous construisons avec vous.'),
('about_points', 'fr', 'Un interlocuteur unique du devis à la mise en ligne\nDes sites rapides, adaptés au mobile et faciles à mettre à jour\nUn référencement local pour être visible dans votre ville'),
('services_title', 'fr', 'Ce que nous faisons pour vous'),
('services_intro', 'fr', 'Quatre métiers complémentaires, pour que votre site, votre image et votre visibilité racontent la même histoire.'),
('why_title', 'fr', 'Pourquoi nous choisir'),
('why_intro', 'fr', 'Nos engagements envers chaque client, quelle que soit la taille du projet.'),
('projects_title', 'fr', 'Nos réalisations'),
('projects_intro', 'fr', 'Des sites, des logos et des contenus livrés pour des entreprises de la région angevine.'),
('reviews_title', 'fr', 'Ce que disent nos clients'),
('contact_title', 'fr', 'Parlons de votre projet'),
('contact_intro', 'fr', 'Décrivez-nous votre besoin en quelques lignes. Nous vous répondons sous 24 h ouvrées avec des premières pistes et un devis gratuit.'),
('legal_notice', 'fr', '## Éditeur du site\n\nHeaven of Web — [forme juridique et capital à compléter]\nSIRET : [à compléter]\nAdresse : [à compléter]\nEmail : contact@heavenofweb.fr\nDirecteur de la publication : [à compléter]\n\n## Hébergement\n\nHostinger International Ltd — 61 Lordou Vironos Street, 6023 Larnaca, Chypre — [www.hostinger.fr](https://www.hostinger.fr)\n\n## Propriété intellectuelle\n\nL’ensemble des contenus de ce site (textes, images, logos, maquettes) est la propriété de Heaven of Web ou de ses clients, qui en ont autorisé la présentation. Toute reproduction sans autorisation écrite est interdite.\n\n## Données personnelles\n\nLe traitement des données envoyées par le formulaire de contact est décrit dans notre [politique de confidentialité](/fr/confidentialite).'),
('privacy', 'fr', '## Données collectées\n\nLorsque vous utilisez le formulaire de contact, nous recevons votre nom, votre adresse email, et si vous les indiquez votre téléphone, votre entreprise, le service souhaité, votre budget et votre message.\n\n## Utilisation\n\nCes informations servent uniquement à répondre à votre demande et à établir un devis. Elles ne sont ni vendues ni transmises à des tiers.\n\n## Durée de conservation\n\nLes messages sont conservés 3 ans après notre dernier échange, puis supprimés.\n\n## Mesure d’audience sans cookie\n\nNous mesurons la fréquentation du site avec un outil interne qui n’utilise aucun cookie et ne conserve pas votre adresse IP : un identifiant anonyme, renouvelé chaque jour, permet seulement de compter les visiteurs. Votre choix de thème (clair ou sombre) est enregistré dans votre navigateur, il ne nous est pas transmis.\n\n## Vos droits\n\nVous pouvez demander l’accès, la rectification ou la suppression de vos données en écrivant à contact@heavenofweb.fr. Vous pouvez aussi adresser une réclamation à la CNIL ([www.cnil.fr](https://www.cnil.fr)).');
INSERT INTO settings (skey, lang, value) VALUES
('meta_title', 'en', 'Heaven of Web — Websites, logos and SEO in Angers, France'),
('meta_description', 'en', 'Web agency in Angers, France: website design, visual identity, search engine optimisation (SEO) and social media content. Free quote.'),
('hero_title', 'en', 'We build your online presence, not just a website.'),
('hero_subtitle', 'en', 'Websites, logos, SEO and social media for tradespeople and businesses that want to be found, then chosen.'),
('about_title', 'en', 'A small team with one goal: a website that brings you customers'),
('about_text', 'en', 'Heaven of Web designs professional websites, visual identities and social media content, with search engine optimisation built in from the very first mock-up.\n\nWe mostly work with tradespeople and companies in construction, energy and services: businesses whose customers search on Google, compare two or three websites, then call the one they trust. That is the website we build with you.'),
('about_points', 'en', 'One contact person from quote to launch\nFast, mobile-friendly websites that are easy to update\nLocal SEO so people in your area can find you'),
('services_title', 'en', 'What we do for you'),
('services_intro', 'en', 'Four complementary skills, so your website, your brand and your visibility tell the same story.'),
('why_title', 'en', 'Why choose us'),
('why_intro', 'en', 'Our commitments to every client, whatever the size of the project.'),
('projects_title', 'en', 'Our work'),
('projects_intro', 'en', 'Websites, logos and content delivered for businesses around Angers.'),
('reviews_title', 'en', 'What our clients say'),
('contact_title', 'en', 'Let’s talk about your project'),
('contact_intro', 'en', 'Tell us what you need in a few lines. We reply within one business day with first ideas and a free quote.'),
('legal_notice', 'en', '## Publisher\n\nHeaven of Web — [legal form to be completed]\nCompany number (SIRET): [to be completed]\nAddress: [to be completed]\nEmail: contact@heavenofweb.fr\n\n## Hosting\n\nHostinger International Ltd — 61 Lordou Vironos Street, 6023 Larnaca, Cyprus — [www.hostinger.com](https://www.hostinger.com)\n\n## Intellectual property\n\nAll content on this website (text, images, logos, designs) belongs to Heaven of Web or to its clients, who have authorised its display. Reproduction without written permission is prohibited.'),
('privacy', 'en', '## Data we collect\n\nWhen you use the contact form we receive your name, your email address and, if you provide them, your phone number, company, the service you are interested in, your budget and your message.\n\n## How we use it\n\nThis information is only used to answer your request and prepare a quote. It is never sold or shared with third parties.\n\n## Retention\n\nMessages are kept for 3 years after our last exchange, then deleted.\n\n## Cookie-free analytics\n\nWe measure traffic with an in-house tool that uses no cookies and does not store your IP address: an anonymous identifier, renewed every day, is only used to count visitors. Your theme preference (light or dark) is stored in your browser and is never sent to us.\n\n## Your rights\n\nYou can ask to access, correct or delete your data by writing to contact@heavenofweb.fr.');
INSERT INTO settings (skey, lang, value) VALUES
('meta_title', 'ar', 'Heaven of Web — تصميم المواقع والشعارات وتحسين محركات البحث'),
('meta_description', 'ar', 'وكالة ويب في أنجيه بفرنسا: تصميم مواقع الإنترنت، الهوية البصرية، تحسين الظهور في محركات البحث ومحتوى الشبكات الاجتماعية. عرض سعر مجاني.'),
('hero_title', 'ar', 'نبني حضورك على الإنترنت، وليس مجرد موقع ويب.'),
('hero_subtitle', 'ar', 'مواقع إنترنت، شعارات، تحسين محركات البحث وشبكات اجتماعية للحرفيين والشركات التي تريد أن يجدها العملاء ثم يختاروها.'),
('about_title', 'ar', 'فريق صغير بهدف واحد: موقع يجلب لك العملاء'),
('about_text', 'ar', 'تصمم Heaven of Web مواقع ويب احترافية وهويات بصرية ومحتوى للشبكات الاجتماعية، مع مراعاة تحسين محركات البحث منذ النموذج الأول.\n\nنعمل أساسًا مع الحرفيين وشركات البناء والطاقة والخدمات: مهن يبحث فيها العميل على Google، ويقارن بين موقعين أو ثلاثة، ثم يتصل بمن يثق به. هذا هو الموقع الذي نبنيه معك.'),
('about_points', 'ar', 'مُحاور واحد من عرض السعر حتى الإطلاق\nمواقع سريعة ومتوافقة مع الجوال وسهلة التحديث\nتحسين محلي لمحركات البحث ليجدك العملاء في مدينتك'),
('services_title', 'ar', 'ما نقدمه لك'),
('services_intro', 'ar', 'أربع مهارات متكاملة، ليحكي موقعك وصورتك وظهورك القصة نفسها.'),
('why_title', 'ar', 'لماذا تختارنا'),
('why_intro', 'ar', 'التزاماتنا تجاه كل عميل، مهما كان حجم المشروع.'),
('projects_title', 'ar', 'أعمالنا'),
('projects_intro', 'ar', 'مواقع وشعارات ومحتوى أنجزناها لشركات في منطقة أنجيه.'),
('reviews_title', 'ar', 'آراء عملائنا'),
('contact_title', 'ar', 'لنتحدث عن مشروعك'),
('contact_intro', 'ar', 'صف لنا حاجتك في بضعة أسطر. نرد عليك خلال يوم عمل واحد بأفكار أولية وعرض سعر مجاني.'),
('legal_notice', 'ar', '## ناشر الموقع\n\nHeaven of Web — [يُستكمل]\nرقم التسجيل (SIRET): [يُستكمل]\nالعنوان: [يُستكمل]\nالبريد الإلكتروني: contact@heavenofweb.fr\n\n## الاستضافة\n\nHostinger International Ltd — 61 Lordou Vironos Street, 6023 Larnaca، قبرص\n\n## الملكية الفكرية\n\nجميع محتويات هذا الموقع (نصوص، صور، شعارات، تصاميم) ملك لـ Heaven of Web أو لعملائها الذين أذنوا بعرضها. يُمنع أي نسخ دون إذن كتابي.'),
('privacy', 'ar', '## البيانات التي نجمعها\n\nعند استخدام نموذج الاتصال نتلقى اسمك وبريدك الإلكتروني، وإن ذكرتها: رقم هاتفك وشركتك والخدمة المطلوبة وميزانيتك ورسالتك.\n\n## الاستخدام\n\nتُستخدم هذه المعلومات فقط للرد على طلبك وإعداد عرض السعر، ولا تُباع ولا تُنقل إلى أي طرف ثالث.\n\n## مدة الحفظ\n\nتُحفظ الرسائل لمدة 3 سنوات بعد آخر تواصل بيننا ثم تُحذف.\n\n## قياس الزيارات دون ملفات تعريف الارتباط\n\nنقيس عدد الزيارات بأداة داخلية لا تستخدم ملفات تعريف الارتباط ولا تحفظ عنوان IP الخاص بك.\n\n## حقوقك\n\nيمكنك طلب الاطلاع على بياناتك أو تصحيحها أو حذفها بالكتابة إلى contact@heavenofweb.fr.');
INSERT INTO services (id, icon, sort) VALUES (1, 'browser', 1), (2, 'pen', 2), (3, 'search', 3), (4, 'megaphone', 4);
INSERT INTO translations (entity, entity_id, lang, field, value) VALUES
('service', 1, 'fr', 'title', 'Création de sites web'),
('service', 1, 'fr', 'text', 'Sites vitrines sur mesure, rapides et adaptés au mobile. Nous partons de vos clients et de vos métiers pour construire des pages claires qui donnent envie de vous appeler.'),
('service', 2, 'fr', 'title', 'Identité visuelle'),
('service', 2, 'fr', 'text', 'Logos, chartes graphiques, cartes de visite et visuels publicitaires : une image cohérente, que l’on reconnaît sur votre camion comme sur Instagram.'),
('service', 3, 'fr', 'title', 'Référencement naturel'),
('service', 3, 'fr', 'text', 'Optimisation technique, contenus ciblés et fiche Google Business Profile, pour apparaître quand vos futurs clients cherchent votre métier dans votre ville.'),
('service', 4, 'fr', 'title', 'Réseaux sociaux et contenus'),
('service', 4, 'fr', 'text', 'Publications, visuels et articles qui montrent vos chantiers et votre savoir-faire, avec un calendrier simple à suivre.'),
('service', 1, 'en', 'title', 'Website design'),
('service', 1, 'en', 'text', 'Custom showcase websites that are fast and mobile-friendly. We start from your customers and your trade to build clear pages that make people want to call you.'),
('service', 2, 'en', 'title', 'Visual identity'),
('service', 2, 'en', 'text', 'Logos, brand guidelines, business cards and ad visuals: a consistent image people recognise on your van as well as on Instagram.'),
('service', 3, 'en', 'title', 'Search engine optimisation'),
('service', 3, 'en', 'text', 'Technical optimisation, targeted content and your Google Business Profile, so you show up when future customers search for your trade in your town.'),
('service', 4, 'en', 'title', 'Social media and content'),
('service', 4, 'en', 'text', 'Posts, visuals and articles that show your work and expertise, with an easy-to-follow publishing calendar.'),
('service', 1, 'ar', 'title', 'تصميم المواقع'),
('service', 1, 'ar', 'text', 'مواقع تعريفية مصممة حسب الطلب، سريعة ومتوافقة مع الجوال. ننطلق من عملائك ومهنتك لبناء صفحات واضحة تشجع الزائر على الاتصال بك.'),
('service', 2, 'ar', 'title', 'الهوية البصرية'),
('service', 2, 'ar', 'text', 'شعارات، أدلة هوية، بطاقات أعمال وتصاميم إعلانية: صورة متناسقة يتعرف عليها الناس على شاحنتك كما على Instagram.'),
('service', 3, 'ar', 'title', 'تحسين محركات البحث'),
('service', 3, 'ar', 'text', 'تحسين تقني ومحتوى موجه وملف Google Business Profile، لتظهر عندما يبحث عملاؤك المستقبليون عن مهنتك في مدينتك.'),
('service', 4, 'ar', 'title', 'الشبكات الاجتماعية والمحتوى'),
('service', 4, 'ar', 'text', 'منشورات وتصاميم ومقالات تُبرز أعمالك وخبرتك، مع جدول نشر سهل المتابعة.');
INSERT INTO features (id, icon, sort) VALUES (1, 'award', 1), (2, 'users', 2), (3, 'bolt', 3), (4, 'heart', 4);
INSERT INTO translations (entity, entity_id, lang, field, value) VALUES
('feature', 1, 'fr', 'title', 'Qualité du service'),
('feature', 1, 'fr', 'text', 'Le même soin pour chaque client, quel que soit son budget : des solutions pensées pour votre activité, pas un modèle recopié.'),
('feature', 2, 'fr', 'title', 'Collaboration efficace'),
('feature', 2, 'fr', 'text', 'Vous validez chaque étape. Un interlocuteur unique répond à vos questions, sans jargon.'),
('feature', 3, 'fr', 'title', 'Rapidité et fiabilité'),
('feature', 3, 'fr', 'text', 'Des délais annoncés dès le devis et tenus. Votre site est sauvegardé, sécurisé et suivi après la mise en ligne.'),
('feature', 4, 'fr', 'title', 'Satisfaction garantie'),
('feature', 4, 'fr', 'text', 'Nous ajustons le travail jusqu’à ce que le résultat vous ressemble. Votre recommandation est notre meilleure publicité.'),
('feature', 1, 'en', 'title', 'Quality of service'),
('feature', 1, 'en', 'text', 'The same care for every client, whatever the budget: solutions designed for your business, not a copied template.'),
('feature', 2, 'en', 'title', 'Effective collaboration'),
('feature', 2, 'en', 'text', 'You approve every step. One contact person answers your questions, without jargon.'),
('feature', 3, 'en', 'title', 'Speed and reliability'),
('feature', 3, 'en', 'text', 'Deadlines set in the quote, and met. Your website is backed up, secured and monitored after launch.'),
('feature', 4, 'en', 'title', 'Satisfaction guaranteed'),
('feature', 4, 'en', 'text', 'We refine the work until the result feels like you. Your recommendation is our best advertising.'),
('feature', 1, 'ar', 'title', 'جودة الخدمة'),
('feature', 1, 'ar', 'text', 'العناية نفسها لكل عميل مهما كانت ميزانيته: حلول مصممة لنشاطك، وليست قالبًا منسوخًا.'),
('feature', 2, 'ar', 'title', 'تعاون فعّال'),
('feature', 2, 'ar', 'text', 'توافق على كل مرحلة، ومُحاور واحد يجيب عن أسئلتك دون مصطلحات معقدة.'),
('feature', 3, 'ar', 'title', 'سرعة وموثوقية'),
('feature', 3, 'ar', 'text', 'مواعيد محددة منذ عرض السعر ويتم احترامها. موقعك محفوظ ومؤمَّن ومتابَع بعد الإطلاق.'),
('feature', 4, 'ar', 'title', 'رضا مضمون'),
('feature', 4, 'ar', 'text', 'نعدّل العمل حتى تجد نفسك في النتيجة. توصيتك هي أفضل إعلان لنا.');
