INSERT INTO translations (entity, entity_id, lang, field, value) VALUES
('project', 1, 'fr', 'title', 'France Énergie Solution'),
('project', 1, 'fr', 'category', 'Site web'),
('project', 1, 'fr', 'summary', 'Site vitrine d’un spécialiste angevin de la rénovation énergétique : pompes à chaleur, ballons thermodynamiques, VMC.'),
('project', 1, 'fr', 'body', 'Un site pensé pour transformer les visites en demandes de devis : une page par équipement, des offres mises en avant dès l’accueil, et un formulaire de contact présent sur chaque page.\n\nLa navigation reste simple sur mobile, où arrivent la plupart des visiteurs.'),
('project', 2, 'fr', 'title', 'Borne Home'),
('project', 2, 'fr', 'category', 'Site web'),
('project', 2, 'fr', 'summary', 'Site d’un installateur de bornes de recharge pour voitures électriques, à Angers.'),
('project', 2, 'fr', 'body', 'Présentation des bornes proposées, des aides financières (TVA réduite, crédit d’impôt) et un parcours clair vers la demande de devis.'),
('project', 3, 'fr', 'title', 'Fenêtre & Confort'),
('project', 3, 'fr', 'category', 'Site web'),
('project', 3, 'fr', 'summary', 'Site d’une entreprise de rénovation de l’habitat : menuiseries PVC et aluminium, isolation, toiture.'),
('project', 3, 'fr', 'body', 'Pages services détaillées, galerie de réalisations, avis clients et coordonnées visibles en permanence pour faciliter la prise de contact.'),
('project', 4, 'fr', 'title', 'IZI Elec'),
('project', 4, 'fr', 'category', 'Site web'),
('project', 4, 'fr', 'summary', 'Site d’une entreprise d’électricité générale : travaux, dépannage et demandes d’intervention.'),
('project', 4, 'fr', 'body', 'Un site direct, avec les boutons « Demande d’intervention » et « Appeler » toujours visibles, et une présentation claire des prestations.'),
('project', 5, 'fr', 'title', 'Logo IZI Elec'),
('project', 5, 'fr', 'category', 'Logo'),
('project', 5, 'fr', 'summary', 'Création du logo et de la mascotte d’IZI Elec.'),
('project', 5, 'fr', 'body', 'Une mascotte d’électricien et une typographie ronde, pour une marque sympathique et facile à reconnaître sur les véhicules et les réseaux sociaux.'),
('project', 6, 'fr', 'title', 'Logo Borne Home'),
('project', 6, 'fr', 'category', 'Logo'),
('project', 6, 'fr', 'summary', 'Création du logo de Borne Home, installateur de bornes de recharge.'),
('project', 6, 'fr', 'body', 'Une voiture et une borne stylisées, en vert et bleu, qui disent le métier au premier coup d’œil.'),
('project', 7, 'fr', 'title', 'France Énergie Solution sur Instagram'),
('project', 7, 'fr', 'category', 'Réseaux sociaux'),
('project', 7, 'fr', 'summary', 'Visuels et publications Instagram pour France Énergie Solution.'),
('project', 7, 'fr', 'body', 'Promotions, photos de chantiers et mascotte de la marque, dans une ligne graphique cohérente avec le site.'),
('project', 8, 'fr', 'title', 'Fenêtre & Confort sur Instagram'),
('project', 8, 'fr', 'category', 'Réseaux sociaux'),
('project', 8, 'fr', 'summary', 'Visuels et publications Instagram pour Fenêtre & Confort.'),
('project', 8, 'fr', 'body', 'Mises en avant des services, offres et réalisations, aux couleurs de l’entreprise.'),
INSERT INTO migrations (name) VALUES ('002_seed');
